const fmtDaftar = new Intl.ListFormat("id-ID", { type: "conjunction" });
function ringkasan(items) {
  const total = items.reduce((t, i) => t + i.harga, 0);
  if (items.length > 1) console.log(`${items.length} item, total Rp${total.toLocaleString("id-ID")}`);
  console.log(fmtDaftar.format(items.map((i) => i.nama)));
}
ringkasan([
  { nama: "kopi", harga: 500000 },
  { nama: "teh", harga: 450000 },
  { nama: "roti", harga: 300000 },
]);
ringkasan([{ nama: "kopi", harga: 18000 }]);
